// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.modelimport java.time.DayOfWeek/** * NOUS — Automation triggers (Module 8). * * Sealed hierarchy describing WHAT fires an [AutomationRule]. Each variant * maps to a concrete Android scheduling primitive: * *   - [TimeTrigger]      → WorkManager `PeriodicWorkRequest` (24h interval, *                          initial delay = ms until next fire). *   - [LocationTrigger]  → `GeofencingClient` (Google Play Services Location). *   - [EventTrigger]     → Dynamic `BroadcastReceiver` registered via *                          `Context.registerReceiver` for the matching *                          system broadcast action. *   - [StateTrigger]     → Dynamic `BroadcastReceiver` for the state-change *                          broadcast (e.g., `ACTION_BATTERY_CHANGED`). *   - [CompoundTrigger]  → No native scheduler — evaluated by *                          [com.roshan.persona.automation.engine.AutomationEngine] *                          when any sub-trigger fires; the [operator] decides *                          whether to fire the parent rule. * * Strategy reference: §2.2 Brain input types — "USER INPUT (Voice/Text/Gesture/ * Automation)" — Automation is one of the four input modalities; this module * is the engine that converts user-defined rules into scheduled Android work. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2</a> */sealed interface AutomationTrigger {    /**     * Time-of-day trigger. Fires every day (or only on [daysOfWeek]) at     * `[hour]:[minute]` local time.     *     * Scheduled via WorkManager `PeriodicWorkRequest` with a 24-hour repeat     * interval. The worker itself checks [daysOfWeek] before firing — empty     * set means "every day".     *     * @param hour       0-23 (24-hour clock).     * @param minute     0-59.     * @param daysOfWeek subset of [DayOfWeek] when this trigger is active.     *                   Empty set = every day.     */    data class TimeTrigger(        val hour: Int,        val minute: Int,        val daysOfWeek: Set<DayOfWeek> = emptySet(),    ) : AutomationTrigger {        init {            require(hour in 0..23) { "hour must be 0..23 — got $hour" }            require(minute in 0..59) { "minute must be 0..59 — got $minute" }        }        /** True if this trigger fires every day (no day-of-week restriction). */        val firesEveryDay: Boolean get() = daysOfWeek.isEmpty()        /** True if this trigger should fire today ([today] is the day to test). */        fun firesOn(today: DayOfWeek): Boolean = firesEveryDay || today in daysOfWeek    }    /**     * Geofence trigger. Fires when the device crosses the geofence boundary     * in the direction specified by [action].     *     * Scheduled via `LocationServices.getGeofencingClient(...)` with a     * never-expiring geofence. Transition events are received by     * [com.roshan.persona.automation.worker.AutomationGeofenceReceiver]     * which forwards them to [AutomationWorker].     *     * Requires `ACCESS_FINE_LOCATION` (and `ACCESS_BACKGROUND_LOCATION` on     * Android 10+ for background geofencing).     *     * @param latitude     geofence center latitude (WGS84).     * @param longitude    geofence center longitude (WGS84).     * @param radiusMeters geofence radius in meters (100-1000 typical).     * @param action       which transition fires the rule.     */    data class LocationTrigger(        val latitude: Double,        val longitude: Double,        val radiusMeters: Float,        val action: LocationAction,    ) : AutomationTrigger {        init {            require(latitude in -90.0..90.0) { "latitude must be -90..90 — got $latitude" }            require(longitude in -180.0..180.0) { "longitude must be -180..180 — got $longitude" }            require(radiusMeters > 0f) { "radiusMeters must be > 0 — got $radiusMeters" }        }    }    /**     * App/system event trigger. Fires when a specific event occurs:     *   - Notification posted by another app (needs NotificationListenerService).     *   - Phone call state changes (needs `READ_PHONE_STATE`).     *   - SMS received (needs `RECEIVE_SMS`).     *   - App launched (needs UsageStatsManager or accessibility).     *   - Screen on/off (system broadcast, no permission).     *     * @param eventType   which event to listen for.     * @param packageName optional filter — only fires for events from this     *                    package. `null` = any package.     */    data class EventTrigger(        val eventType: EventType,        val packageName: String? = null,    ) : AutomationTrigger    /**     * Device state trigger. Fires when a device-state predicate becomes true.     *     *   - CHARGING            → `ACTION_POWER_CONNECTED` (charging started).     *   - BATTERY_LEVEL       → `ACTION_BATTERY_CHANGED` with [value] = threshold     *                            (e.g., "20" = battery dropped to 20%).     *   - WIFI_CONNECTED      → `NETWORK_STATE_CHANGED_ACTION` for Wi-Fi.     *   - BLUETOOTH_CONNECTED → `ACTION_ACL_CONNECTED`.     *   - HEADPHONES_CONNECTED→ `ACTION_HEADSET_PLUG`.     *   - POWER_CONNECTED     → `ACTION_POWER_CONNECTED` (any power source).     *   - NETWORK_AVAILABLE   → `CONNECTIVITY_ACTION` (any network).     *     * @param stateType which device state to watch.     * @param value     state-specific threshold or qualifier (e.g., "20" for     *                  battery level). For boolean states, use "true".     */    data class StateTrigger(        val stateType: StateType,        val value: String,    ) : AutomationTrigger    /**     * Compound trigger — combines multiple triggers with a logical operator.     *     * For `AND`: the parent rule fires only when ALL sub-triggers have fired     * within a 5-minute window (configurable in a future revision).     *     * For `OR`: the parent rule fires when ANY sub-trigger fires (this is the     * common case — "fire on weekdays at 7am OR when I arrive at work").     *     * Compound triggers are NOT scheduled directly. Each sub-trigger is     * scheduled individually by     * [com.roshan.persona.automation.scheduler.AutomationScheduler]. When any     * sub-trigger fires, [AutomationEngine] evaluates the [operator] against     * the recent fire history of the sibling triggers and decides whether to     * fire the parent rule.     *     * @param triggers child triggers (must be non-empty).     * @param operator AND / OR.     */    data class CompoundTrigger(        val triggers: List<AutomationTrigger>,        val operator: LogicalOperator,    ) : AutomationTrigger {        init {            require(triggers.isNotEmpty()) { "CompoundTrigger must have at least one child" }        }    }}/** * Geofence transition direction. */enum class LocationAction {    /** Fire when device enters the geofence. */    ENTER,    /** Fire when device exits the geofence. */    EXIT,    /** Fire when device stays inside the geofence for ~30s (dwelling). */    DWELL,}/** * System event types that can fire an [EventTrigger]. */enum class EventType {    /** A notification was posted by another app (needs NotificationListenerService). */    NOTIFICATION_RECEIVED,    /** An incoming call started ringing. */    CALL_INCOMING,    /** A call was answered. */    CALL_ANSWERED,    /** A call ended (any reason). */    CALL_ENDED,    /** An SMS was received. */    SMS_RECEIVED,    /** An app was launched to the foreground. */    APP_LAUNCHED,    /** The screen turned on. */    SCREEN_ON,    /** The screen turned off. */    SCREEN_OFF,    /** The device finished booting. */    BOOT_COMPLETED,    /** A user-presented unlock event (device unlocked by user). */    USER_PRESENT,}/** * Device state types that can fire a [StateTrigger]. */enum class StateType {    /** Power connected (any source — AC or USB). */    CHARGING,    /** Battery level threshold — [StateTrigger.value] is the integer percent. */    BATTERY_LEVEL,    /** Wi-Fi connected (any SSID). */    WIFI_CONNECTED,    /** Bluetooth device connected (any). */    BLUETOOTH_CONNECTED,    /** Wired or wireless headphones connected. */    HEADPHONES_CONNECTED,    /** Power disconnected. */    POWER_DISCONNECTED,    /** Any network became available (Wi-Fi or cellular). */    NETWORK_AVAILABLE,}/** * Logical operator for [AutomationTrigger.CompoundTrigger]. */enum class LogicalOperator {    /** All child triggers must fire (within the recent-fire window). */    AND,    /** Any child trigger firing causes the parent to fire. */    OR,}